import {repository, validateVisitor, evaluateAccess, recordAccess, csvExport, normalizeRfid} from './data.mjs';
const $ = (s, root = document) => root.querySelector(s);
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
 grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 4v3"/>',
 ruler:'<rect x="7" y="2" width="10" height="20" rx="1"/><path d="M7 6h5m-5 4h3m-3 4h5m-5 4h3"/>',
 gate:'<path d="M3 21V8h18v13M7 21V12m5 9V12m5 9V12M2 8l10-5 10 5"/>',
 ticket:'<path d="M3 5h18v5a2 2 0 0 0 0 4v5H3v-5a2 2 0 0 0 0-4V5Z"/><path d="M15 5v3m0 3v2m0 3v3"/>',
 history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7m2-5v6l4 2"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
 arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',
 settings:'<path d="M4 7h16M4 17h16"/><rect x="7" y="4" width="4" height="6" rx="1"/><rect x="14" y="14" width="4" height="6" rx="1"/>',
 scan:'<path d="M3 8V3h5m8 0h5v5M3 16v5h5m8 0h5v-5M6 12h12"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.info}</svg>`;
const initial = name => name.trim().split(/\s+/).slice(0,2).map(s => s[0]).join('').toUpperCase();
const time = iso => new Date(iso).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jakarta'});
const date = iso => new Date(iso).toLocaleDateString('id-ID',{day:'numeric',month:'short',timeZone:'Asia/Jakarta'});
const today = () => new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Jakarta'});
const navs = [['ringkasan','grid','Ringkasan'],['pengunjung','people','Data pengunjung'],['pengukuran','ruler','Pengukuran tinggi'],['akses','gate','Validasi akses'],['wahana','ticket','Kelola wahana'],['riwayat','history','Riwayat akses']];
let state, route = 'ringkasan', query = '', filter = 'semua', logFilter = 'semua', stationVisitor = '', scenario = '168', busy = false, lastAccess = null, toastTimer;
const modal = $('#modal');
function toast(message, error = false) { const el = $('#toast'); el.textContent = message; el.className = error ? 'show error' : 'show'; clearTimeout(toastTimer); toastTimer = setTimeout(() => el.className = '',5000); }
function commit(change) { if(JSON.stringify(repository.load())!==JSON.stringify(state)) throw new Error('Data telah berubah di tab lain. Muat ulang halaman sebelum menyimpan agar perubahan lain tidak tertimpa.'); const next = structuredClone(state); change(next); repository.save(next); state = next; }
function showError(error) { toast(error.message || 'Perubahan belum tersimpan. Coba lagi.',true); }
function routeName() { return navs.find(n => n[0] === route)?.[2] || 'Ringkasan'; }
function header(title, subtitle, actions = '') { return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`; }
const addButton = () => `<button class="btn primary" data-action="add">${icon('plus')} Daftarkan pengunjung</button>`;
function metric(label,value,unit,note,symbol,cls='') {
 return `<div class="metric ${cls}"><div class="metric-value"><strong>${value}</strong><span>${unit}</span></div><div class="metric-label"><span>${label}</span><small>${note}</small></div></div>`;
}
function render() {
 document.title = `${routeName()} | COCOMANG`;
 const ready = state.visitors.filter(v => v.height !== null).length;
 $('#app').innerHTML = `<div class="app-shell">
  <header class="masthead"><div class="masthead-inner">
   <a class="brand" href="#ringkasan" aria-label="COCOMANG, ringkasan"><span class="brand-name">COCOMANG</span><span class="brand-caption">Taman bermain & petualangan</span></a>
   <div class="desk-identity"><span>Meja petugas</span><strong>Loket utama</strong></div>
   <div class="operator"><span class="mode-label">Mode simulasi</span><button class="icon-button" data-action="help" aria-label="Panduan simulasi">${icon('info')}</button></div>
  </div></header>
  <nav class="nav-list" aria-label="Navigasi utama">${navs.map(([id,symbol,label],i)=>`<a class="nav-link ${route===id?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''}><span class="nav-number" aria-hidden="true">0${i+1}</span><span>${label}</span></a>`).join('')}</nav>
  <div class="workspace"><div class="topbar"><span class="breadcrumb">Operasional <span>/</span><strong>${routeName()}</strong></span><span class="date-label">${today()}</span></div>
  <main id="main" tabindex="-1">${route==='ringkasan'?dashboard(ready):route==='pengunjung'?visitorsPage():route==='pengukuran'?measurementPage():route==='akses'?accessPage():route==='wahana'?ridesPage():historyPage()}
   <footer class="workspace-footer"><div><strong>COCOMANG</strong><span>Wahana & data awal adalah contoh.</span></div><button class="link-plain" data-action="help">Disimpan di browser ini · Tentang simulasi</button></footer>
  </main></div></div>`;
 bindPage();
}
function dashboard(ready) {
 return header('Siap untuk bermain.','Daftarkan pengunjung, ukur tinggi, lalu periksa akses wahananya.',`<button class="btn" data-action="export-visitors">${icon('download')} Ekspor data</button>${addButton()}`)+`
 <section class="metrics" aria-label="Ringkasan data simulasi">
  ${metric('Pengunjung terdaftar',state.visitors.length,'orang','Data simulasi','people')}
  ${metric('Sudah diukur',ready,'orang','Hasil tinggi tersedia','ruler')}
  ${metric('Menunggu diukur',state.visitors.length-ready,'orang','Lanjutkan di pos ukur','clock','attention')}
  ${metric('Wahana dibuka',state.rides.filter(r=>r.status==='Buka').length,`/ ${state.rides.length}`,'Sesuai status operasional','ticket')}
 </section>
 <div class="dashboard-grid"><div class="ledger-column">
  <section class="panel visitor-ledger"><div class="panel-header"><div><h2>Pengunjung terdaftar <span class="count">${state.visitors.length}</span></h2><p>Cari nama atau kartu untuk melihat data dan kelayakan wahana.</p></div></div>${visitorFilters()}<div id="visitor-table">${visitorTable()}</div></section>
  <section class="activity-section section-gap"><div class="panel-header"><h2>Pemeriksaan terakhir</h2><a class="text-button" href="#riwayat">Semua riwayat ${icon('arrow')}</a></div>${logTable(state.logs.slice(0,3),true)}</section>
 </div><div class="right-column">${station()}
  <section class="height-guide section-gap"><div class="panel-header"><h2>Catatan batas tinggi</h2><a class="text-button" href="#wahana">Atur</a></div><div class="ride-summary">${[...state.rides].sort((a,b)=>a.minHeight-b.minHeight).map(r=>`<div class="ride-line"><span>${escape(r.name)}</span><strong>${r.minHeight}<small> cm</small></strong></div>`).join('')}</div><p class="guide-footnote">Batas minimum contoh. Cek ketentuan sebelum validasi akses.</p></section>
 </div></div>`;
}
function visitorFilters() {return `<div class="filters"><div class="search-field"><label class="field-caption" for="visitor-search">Cari pengunjung</label><div class="search-wrap">${icon('search')}<input id="visitor-search" placeholder="Nama atau UID RFID…" value="${escape(query)}" autocomplete="off"></div></div><div><label class="field-caption" for="visitor-filter">Status pengukuran</label><select id="visitor-filter"><option value="semua" ${filter==='semua'?'selected':''}>Semua status</option><option value="ready" ${filter==='ready'?'selected':''}>Sudah diukur</option><option value="waiting" ${filter==='waiting'?'selected':''}>Belum diukur</option></select></div></div>`;}
function filteredVisitors() { return state.visitors.filter(v=>(v.name.toLowerCase().includes(query.toLowerCase()) || v.rfid.includes(normalizeRfid(query))) && (filter==='semua' || (filter==='ready'?v.height!==null:v.height===null))); }
function visitorTable() {
 const rows = filteredVisitors(), visible = route==='ringkasan'?rows.slice(0,6):rows;
 if(!rows.length) return `<div class="empty"><strong>Tidak ada pengunjung yang ditemukan.</strong>Coba nama lain, ubah filter, atau daftarkan pengunjung baru.</div>`;
 return `<div class="table-scroll"><table><thead><tr><th scope="col">Pengunjung</th><th scope="col">Tinggi</th><th scope="col">Berat</th><th scope="col" class="rfid-column">Kartu RFID</th><th scope="col">Pengukuran</th><th scope="col">Detail</th></tr></thead><tbody>${visible.map(v=>`<tr><td><div class="person"><strong>${escape(v.name)}</strong><small>${v.age} tahun · ${escape(v.gender)}</small></div></td><td class="numeric height-cell">${v.height===null?'<span class="muted">Belum ada</span>':`${v.height} <small>cm</small>`}</td><td class="numeric">${v.weight} <small>kg</small></td><td class="rfid-column numeric uid">${escape(v.rfid)}</td><td><span class="status ${v.height===null?'waiting':''}">${v.height===null?'Belum diukur':'Sudah diukur'}</span></td><td><button class="text-button" data-action="detail" data-id="${escape(v.id)}" aria-label="Detail ${escape(v.name)}">Buka</button></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${visible.length} dari ${rows.length} pengunjung</span>${route==='ringkasan'?'<a class="text-button" href="#pengunjung">Semua pengunjung</a>':'<span>Data tersimpan lokal</span>'}</div>`;
}
function visitorsPage(){return header('Data pengunjung','Daftarkan identitas pengunjung dan hubungkan dengan kartu RFID.',`<button class="btn" data-action="export-visitors">${icon('download')} Ekspor CSV</button>${addButton()}`)+`<section class="panel"><div class="panel-header"><h2>Daftar pengunjung <span class="count">${state.visitors.length}</span></h2></div>${visitorFilters()}<div id="visitor-table">${visitorTable()}</div></section>`;}
function visitorOptions(selected){return state.visitors.map(v=>`<option value="${escape(v.id)}" ${v.id===selected?'selected':''}>${escape(v.name)} · ${escape(v.rfid)}</option>`).join('');}
function station(){
 if(!state.visitors.find(v=>v.id===stationVisitor)) stationVisitor=state.visitors.find(v=>v.height===null)?.id || state.visitors[0]?.id || '';
 const v=state.visitors.find(v=>v.id===stationVisitor);
 return `<section class="panel station"><div class="panel-header"><div><span class="station-kicker">POS UKUR / SENSOR VIRTUAL</span><h2>Tinggi badan</h2></div>${icon('ruler')}</div><div class="station-body">
  <label class="field-caption" for="station-visitor">Pengunjung yang diukur</label><select id="station-visitor" ${busy?'disabled':''}>${v?visitorOptions(stationVisitor):'<option>Belum ada pengunjung</option>'}</select>
  <div class="measurement ${busy?'sensor-busy':''}" aria-live="polite"><div class="measurement-label">${busy?'Sedang membaca':'Hasil pengukuran'}</div><div class="height-value"><strong>${busy?'…':v?.height??'–'}</strong><span>cm</span></div><p class="measurement-caption">${busy?'Membaca jarak sensor…':v?.height?`${time(v.measuredAt)} WIB · hasil simulasi`:'Pilih skenario, lalu mulai pengukuran.'}</p><div class="ruler" aria-hidden="true"><span>200</span><span>100</span><span>0</span>${!busy&&v?.height!==null&&v?.height!==undefined?`<i class="height-marker" style="top:${Math.max(0,100-v.height/2)}%"></i>`:''}</div></div>
  <div class="sensor-options"><label class="field-caption" for="sensor-scenario">Skenario sensor</label><select id="sensor-scenario" ${busy?'disabled':''}><option value="110" ${scenario==='110'?'selected':''}>Anak · jarak 90 cm</option><option value="138" ${scenario==='138'?'selected':''}>Remaja · jarak 62 cm</option><option value="168" ${scenario==='168'?'selected':''}>Dewasa · jarak 32 cm</option><option value="error" ${scenario==='error'?'selected':''}>Uji kegagalan pembacaan</option></select></div>
  <p class="sensor-help">Tinggi = 200 cm − jarak sensor ke kepala.</p><button class="btn green full" data-action="measure" ${busy||!v?'disabled':''}>${icon('scan')} ${busy?'Mengukur…':v?.height?'Ukur ulang tinggi':'Simulasikan pengukuran'}</button><div class="device-status"><span>HC-SR04 / ESP32</span><span>Belum terhubung</span></div>
 </div></section>`;
}
function measurementPage(){return header('Pengukuran tinggi','Tinggi badan diterima dari sensor, bukan diketik pada formulir pendaftaran.')+`<div class="wide-grid"><section class="panel info-panel"><h2>Dari kartu ke hasil ukur.</h2><p>Pilih pengunjung terdaftar, lalu jalankan skenario sensor untuk mencoba pengukuran tinggi.</p><ol class="steps"><li><div><strong>Identifikasi pengunjung</strong>Gunakan nama dan UID RFID yang sudah didaftarkan oleh petugas.</div></li><li><div><strong>Baca jarak dari sensor</strong>Pada simulasi ini, skenario mewakili objek yang berada di bawah sensor dengan tinggi referensi 200 cm.</div></li><li><div><strong>Simpan hasil dan cek wahana</strong>Hasil pengukuran diperbarui pada data pengunjung. Kelayakan wahana dihitung dari hasil terbaru.</div></li></ol><div class="notice">Simulasi belum terhubung ESP32. Tinggi pemasangan dan akurasi sensor fisik perlu dikalibrasi saat integrasi.</div><h3>Pengunjung menunggu pengukuran</h3>${state.visitors.filter(v=>v.height===null).length?`<ul class="info-list">${state.visitors.filter(v=>v.height===null).map(v=>`<li><span>${escape(v.name)}</span><button class="text-button" data-action="select-measure" data-id="${escape(v.id)}">Pilih ${icon('arrow')}</button></li>`).join('')}</ul>`:'<p>Semua pengunjung sudah memiliki hasil pengukuran.</p>'}</section>${station()}</div>`;}
function accessPage(){return header('Validasi akses wahana','Simulasikan kartu di gerbang dan periksa syarat masuk wahana.')+`<div class="wide-grid"><section class="panel"><div class="panel-header"><div><h2>Pemeriksaan gerbang</h2><p>Hasil pemeriksaan otomatis dicatat ke riwayat akses.</p></div></div><form id="access-form" class="access-form"><div class="field"><label for="access-visitor">Pengunjung / kartu RFID</label><select id="access-visitor" name="visitorId" required><option value="">Pilih pengunjung</option>${visitorOptions(lastAccess?.visitorId)}</select></div><div class="field"><label for="access-ride">Wahana tujuan</label><select id="access-ride" name="rideId" required><option value="">Pilih wahana</option>${state.rides.map(r=>`<option value="${escape(r.id)}" ${lastAccess?.rideId===r.id?'selected':''}>${escape(r.name)} · min. ${r.minHeight} cm${r.status==='Perawatan'?' · Perawatan':''}</option>`).join('')}</select></div><button class="btn green" type="submit">${icon('scan')} Simulasikan tap RFID</button><div id="access-result" aria-live="polite">${lastAccess?accessResult(lastAccess):''}</div></form></section><section class="panel info-panel"><h2>Keputusan yang bisa ditelusuri</h2><p>Akses diperiksa dari data tersimpan dan aturan wahana yang aktif.</p><ul class="info-list"><li><span>Kartu pengunjung</span><strong>Harus terdaftar</strong></li><li><span>Hasil tinggi badan</span><strong>Harus tersedia</strong></li><li><span>Batas tinggi</span><strong>Sesuai wahana</strong></li><li><span>Batas berat</span><strong>Jika ditetapkan</strong></li><li><span>Status wahana</span><strong>Harus buka</strong></li></ul><p>Keputusan ini hanya hasil simulasi aturan. Tidak ada gerbang fisik yang dibuka.</p><a class="btn full" href="#riwayat">${icon('history')} Buka riwayat akses</a></section></div>`;}
function accessResult(entry){return `<div class="result ${entry.allowed?'':'denied'}"><h3>${entry.allowed?'Akses diizinkan':'Akses ditolak'}</h3><p>${escape(entry.reason)}</p><div class="result-meta">${escape(entry.visitorName)} · ${escape(entry.rideName)}<br>${date(entry.createdAt)}, ${time(entry.createdAt)} WIB · Tercatat sebagai simulasi</div></div>`;}
function ridesPage(){return header('Ketentuan wahana.','Atur batas tinggi dan status operasional untuk setiap wahana contoh.')+`<div class="notice">Ketentuan contoh untuk pengujian. Bukan standar keselamatan wahana nyata.</div><section class="ride-catalog" aria-label="Daftar wahana">${state.rides.map((r,i)=>`<article class="ride-card"><span class="ride-number" aria-hidden="true">0${i+1}</span><div class="ride-copy"><small class="muted">${escape(r.category)}</small><h2>${escape(r.name)}</h2><p>${escape(r.description)}</p></div><div class="ride-limit"><strong>${r.minHeight}<small> cm</small></strong><span>Tinggi minimum</span></div><div class="ride-weight"><strong>${r.maxWeight?`${r.maxWeight} kg`:'Tidak dibatasi'}</strong><span>Berat maksimum</span></div><div class="ride-card-foot"><span class="status ${r.status==='Buka'?'':'waiting'}">${escape(r.status)}</span><button class="text-button" data-action="edit-ride" data-id="${escape(r.id)}">Atur wahana ${icon('settings')}</button></div></article>`).join('')}</section>`;}
function logTable(logs,compact=false){if(!logs.length)return '<div class="empty"><strong>Belum ada riwayat akses.</strong>Jalankan pemeriksaan di menu Validasi akses.</div>';return `<div class="table-scroll"><table><thead><tr><th scope="col">Pengunjung</th><th scope="col">Wahana</th><th scope="col">Hasil</th><th scope="col">Waktu</th>${compact?'':'<th scope="col">Alasan keputusan</th>'}</tr></thead><tbody>${logs.map(l=>`<tr><td><strong style="font-weight:500">${escape(l.visitorName)}</strong></td><td>${escape(l.rideName)}</td><td><span class="status ${l.allowed?'':'denied'}">${l.allowed?'Diizinkan':'Ditolak'}</span></td><td class="numeric"><small>${time(l.createdAt)} WIB${compact?'':`<br>${date(l.createdAt)}`}</small></td>${compact?'':`<td>${escape(l.reason)}</td>`}</tr>`).join('')}</tbody></table></div>`;}
function historyPage(){const logs=state.logs.filter(l=>logFilter==='semua'||(logFilter==='allowed'?l.allowed:!l.allowed));return header('Riwayat akses','Catatan keputusan gerbang beserta alasan dan waktu pemeriksaan.',`<button class="btn" data-action="export-logs">${icon('download')} Ekspor riwayat</button>`)+`<section class="panel"><div class="panel-header"><div><h2>Catatan pemeriksaan <span class="count">${logs.length}</span></h2><p>Perubahan aturan tidak mengubah hasil pemeriksaan terdahulu.</p></div><div><label for="log-filter" class="field-caption">Hasil akses</label><select id="log-filter"><option value="semua" ${logFilter==='semua'?'selected':''}>Semua hasil</option><option value="allowed" ${logFilter==='allowed'?'selected':''}>Diizinkan</option><option value="denied" ${logFilter==='denied'?'selected':''}>Ditolak</option></select></div></div>${logTable(logs)}</section>`;}
function bindPage(){
 $('#visitor-search')?.addEventListener('input',e=>{query=e.target.value;$('#visitor-table').innerHTML=visitorTable();});
 $('#visitor-filter')?.addEventListener('change',e=>{filter=e.target.value;$('#visitor-table').innerHTML=visitorTable();});
 $('#station-visitor')?.addEventListener('change',e=>{stationVisitor=e.target.value;render();$('#station-visitor')?.focus();});
 $('#sensor-scenario')?.addEventListener('change',e=>scenario=e.target.value);
 $('#log-filter')?.addEventListener('change',e=>{logFilter=e.target.value;render();$('#log-filter')?.focus();});
 $('#access-form')?.addEventListener('submit',e=>{e.preventDefault();try{const fd=new FormData(e.target);let entry;commit(next=>{entry=recordAccess(next,fd.get('visitorId'),fd.get('rideId'));});lastAccess=entry;$('#access-result').innerHTML=accessResult(entry);toast('Pemeriksaan akses tersimpan.');}catch(error){showError(error);}});
}
function openModal(title,subtitle,content){modal.innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${escape(title)}</h2><p>${escape(subtitle)}</p></div><button class="icon-button" data-action="close" aria-label="Tutup dialog">${icon('close')}</button></div><div class="modal-content">${content}</div>`;if(!modal.open)modal.showModal();}
function field(name,label,type,value='',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${escape(value)}" ${extra}><span class="field-error" id="error-${name}"></span></div>`;}
function visitorForm(id){const v=state.visitors.find(v=>v.id===id);openModal(v?'Ubah data pengunjung':'Daftarkan pengunjung','Isi identitas pengunjung. Tinggi badan diukur terpisah melalui sensor.',`<form id="visitor-form" novalidate><div id="form-error" role="alert"></div><div class="form-grid"><div class="span-2">${field('name','Nama lengkap *','text',v?.name,'required minlength="2" maxlength="100" autocomplete="name"')}</div>${field('age','Usia (tahun) *','number',v?.age,'required min="1" max="120" step="1"')}<div class="field"><label for="f-gender">Jenis kelamin *</label><select id="f-gender" name="gender" required><option value="">Pilih jenis kelamin</option>${['Laki-laki','Perempuan'].map(g=>`<option ${g===v?.gender?'selected':''}>${g}</option>`).join('')}</select><span class="field-error" id="error-gender"></span></div>${field('weight','Berat badan (kg) *','number',v?.weight,'required min="5" max="250" step="0.1"')}${field('phone','Telepon / wali (opsional)','tel',v?.phone,'autocomplete="tel" maxlength="20"')}<div class="field span-2"><label for="f-rfid">UID kartu RFID *</label><div class="input-action"><input id="f-rfid" name="rfid" value="${escape(v?.rfid)}" required maxlength="29" placeholder="Contoh: A1B2C309" autocomplete="off"><button class="btn" type="button" data-action="scan-card">${icon('scan')} Simulasi kartu</button></div><span class="field-error" id="error-rfid"></span><small>Masukkan UID atau gunakan kartu virtual untuk simulasi.</small></div><div class="field span-2"><label for="f-notes">Catatan petugas (opsional)</label><textarea id="f-notes" name="notes" rows="2" maxlength="1000" placeholder="Misalnya: datang bersama wali">${escape(v?.notes)}</textarea><span class="field-error" id="error-notes"></span></div></div><div class="notice">${v?.height?`Tinggi tersimpan: ${v.height} cm. Perubahan tinggi dilakukan melalui pos pengukuran.`:'Tinggi badan belum diisi. Lanjutkan pengukuran setelah data disimpan.'}</div><div class="modal-actions"><button type="button" class="btn" data-action="close">Batal</button><button type="submit" class="btn primary">${v?'Simpan perubahan':'Simpan pengunjung'}</button></div></form>`);
 $('#visitor-form').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const errors=validateVisitor(data,state.visitors,id);e.target.querySelectorAll('.field-error').forEach(el=>el.textContent='');e.target.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));if(Object.keys(errors).length){$('#form-error').innerHTML='<p class="error-banner">Periksa kolom yang ditandai sebelum menyimpan.</p>';for(const [key,msg] of Object.entries(errors)){const el=$(`#f-${key}`);el?.setAttribute('aria-invalid','true');el?.setAttribute('aria-describedby',`error-${key}`);$(`#error-${key}`).textContent=msg;}$(`#f-${Object.keys(errors)[0]}`)?.focus();return;}try{const visitor={...v,...data,id:id||`visitor-${crypto.randomUUID()}`,name:data.name.trim(),age:Number(data.age),weight:Number(data.weight),phone:data.phone.trim(),rfid:normalizeRfid(data.rfid),height:v?.height??null,measuredAt:v?.measuredAt??null,createdAt:v?.createdAt||new Date().toISOString(),demo:true};commit(next=>{if(v)next.visitors[next.visitors.findIndex(item=>item.id===id)]=visitor;else next.visitors.unshift(visitor);});stationVisitor=visitor.id;query='';filter='semua';modal.close();render();toast(v?'Data pengunjung diperbarui.':'Pengunjung tersimpan. Lanjutkan ke pos pengukuran.');}catch(error){$('#form-error').innerHTML=`<p class="error-banner">${escape(error.message)}</p>`;}});
}
function visitorDetail(id){const v=state.visitors.find(v=>v.id===id);if(!v)return;openModal('Detail pengunjung','Data pada sesi simulasi ini.',`<div class="profile-heading"><span class="avatar">${escape(initial(v.name))}</span><div><h3>${escape(v.name)}</h3><p class="muted small">UID ${escape(v.rfid)}</p></div></div><dl class="detail-grid"><div><dt>Usia / jenis kelamin</dt><dd>${v.age} tahun · ${escape(v.gender)}</dd></div><div><dt>Berat badan</dt><dd>${v.weight} kg</dd></div><div><dt>Tinggi dari sensor</dt><dd>${v.height===null?'Belum diukur':`${v.height} cm`}</dd></div><div><dt>Telepon / wali</dt><dd>${escape(v.phone)||'Tidak diisi'}</dd></div></dl>${v.notes?`<p class="small muted" style="margin-bottom:20px;overflow-wrap:anywhere">${escape(v.notes)}</p>`:''}<h3>Kelayakan wahana saat ini</h3>${state.rides.map(r=>{const result=evaluateAccess(v,r);return `<div class="eligibility-row"><div>${escape(r.name)}<small>${escape(result.reason)}</small></div><span class="status ${result.allowed?'':'waiting'}" style="align-self:start">${result.allowed?'Memenuhi':'Belum memenuhi'}</span></div>`;}).join('')}<div class="modal-actions"><button class="btn" data-action="edit-visitor" data-id="${escape(id)}">Ubah data</button><button class="btn green" data-action="goto-measure" data-id="${escape(id)}">${icon('ruler')} ${v.height===null?'Ukur tinggi':'Ukur ulang'}</button></div>`);}
function rideForm(id){const r=state.rides.find(r=>r.id===id);openModal('Atur wahana',r.name,`<form id="ride-form"><div id="ride-error" role="alert"></div>${field('ride-name','Nama wahana','text',r.name,'required maxlength="80"')}${field('minHeight','Tinggi minimum (cm)','number',r.minHeight,'required min="30" max="250" step="1"')}${field('maxWeight','Berat maksimum (kg, opsional)','number',r.maxWeight??'','min="5" max="250" step="0.1"')}<div class="field"><label for="ride-status">Status operasional</label><select id="ride-status" name="status"><option ${r.status==='Buka'?'selected':''}>Buka</option><option ${r.status==='Perawatan'?'selected':''}>Perawatan</option></select></div><p class="small muted">Aturan baru berlaku untuk pemeriksaan selanjutnya. Riwayat terdahulu tetap tersimpan.</p><div class="modal-actions"><button type="button" class="btn" data-action="close">Batal</button><button class="btn primary" type="submit">Simpan ketentuan</button></div></form>`);$('#ride-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target);try{if(!fd.get('ride-name').trim())throw new Error('Nama wahana wajib diisi.');commit(next=>{const ride=next.rides.find(r=>r.id===id);Object.assign(ride,{name:fd.get('ride-name').trim(),minHeight:Number(fd.get('minHeight')),maxWeight:fd.get('maxWeight')===''?null:Number(fd.get('maxWeight')),status:fd.get('status')});});lastAccess=null;modal.close();render();toast('Ketentuan wahana diperbarui.');}catch(error){$('#ride-error').innerHTML=`<p class="error-banner">${escape(error.message)}</p>`;}});}
async function measure(){if(busy||!stationVisitor)return;const id=stationVisitor;const selectedScenario=scenario;busy=true;render();await new Promise(resolve=>setTimeout(resolve,1300));try{if(selectedScenario==='error')throw new Error('Sensor tidak menerima pantulan. Hasil sebelumnya dipertahankan. Pilih skenario lain untuk mencoba lagi.');const referenceHeight=200;const distance=referenceHeight-Number(selectedScenario);commit(next=>{const v=next.visitors.find(v=>v.id===id);v.height=referenceHeight-distance;v.measuredAt=new Date().toISOString();});lastAccess=null;toast(`Hasil ${Number(selectedScenario)} cm tersimpan untuk ${state.visitors.find(v=>v.id===id).name}.`);}catch(error){showError(error);}finally{busy=false;render();$('[data-action="measure"]')?.focus();}}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('File ekspor disiapkan.');}
function exportVisitors(){const rows=state.visitors.map(v=>({'Nama':v.name,'UID RFID':v.rfid,'Usia':v.age,'Jenis kelamin':v.gender,'Berat (kg)':v.weight,'Tinggi (cm)':v.height,'Telepon':v.phone,'Diukur pada':v.measuredAt,'Catatan':v.notes}));download('cocomang-pengunjung.csv',csvExport(rows),'text/csv;charset=utf-8');}
function help(){openModal('Tentang ruang simulasi','COCOMANG · Dashboard petugas',`<p class="small">Daftarkan pengunjung, simulasikan tinggi badan, lalu cek akses wahana berdasarkan kartu RFID.</p><ul class="info-list"><li><span>Penyimpanan</span><strong>Browser perangkat ini</strong></li><li><span>Firebase</span><strong>Belum terhubung</strong></li><li><span>ESP32 dan RFID</span><strong>Disimulasikan</strong></li><li><span>Nama dan batas wahana</span><strong>Data contoh</strong></li></ul><div class="hr"></div><p class="small muted">Data tidak tersinkron ke perangkat lain. Menghapus data situs di browser akan menghapus perubahan. Gunakan ekspor untuk menyimpan salinan sebelum berpindah perangkat.</p><div class="modal-actions"><button class="btn" data-action="export-backup">${icon('download')} Unduh cadangan JSON</button><button class="btn green" data-action="close">Mengerti</button></div>`);}
// One delegated click handler also covers table rows refreshed by filtering.
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action,id=target.dataset.id;
 if(action==='close')modal.close();else if(action==='add')visitorForm();else if(action==='detail')visitorDetail(id);else if(action==='edit-visitor')visitorForm(id);else if(action==='edit-ride')rideForm(id);else if(action==='measure')measure();else if(action==='select-measure'){stationVisitor=id;render();$('#station-visitor')?.focus();}else if(action==='goto-measure'){stationVisitor=id;modal.close();if(location.hash==='#pengukuran')render();else location.hash='pengukuran';}else if(action==='scan-card'){let card;do{card=Array.from(crypto.getRandomValues(new Uint8Array(4)),n=>n.toString(16).padStart(2,'0')).join('').toUpperCase();}while(state.visitors.some(v=>v.rfid===card));$('#f-rfid').value=card;toast('Kartu virtual berhasil dibaca.');}else if(action==='export-visitors')exportVisitors();else if(action==='export-logs')download('cocomang-riwayat.csv',csvExport(state.logs.map(l=>({'Pengunjung':l.visitorName,'Wahana':l.rideName,'Keputusan':l.allowed?'Diizinkan':'Ditolak','Alasan':l.reason,'Tinggi (cm)':l.height,'Waktu':l.createdAt}))),'text/csv;charset=utf-8');else if(action==='export-backup')download('cocomang-cadangan.json',JSON.stringify(state,null,2),'application/json');else if(action==='help')help();else if(action==='retry')boot();
});
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();$('#main')?.focus();});
window.addEventListener('hashchange',()=>{route=navs.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'ringkasan';if(state){render();$('#main').focus({preventScroll:true});window.scrollTo(0,0);}});
window.addEventListener('storage',e=>{if((e.key==='senandika-v1'||e.key===null)&&state){if(modal.open||busy){toast('Data berubah di tab lain. Muat ulang sebelum melanjutkan perubahan.',true);return;}try{state=repository.load();lastAccess=null;render();toast('Data diperbarui dari tab lain.');}catch(error){showError(error);}}});
function boot(){try{state=repository.load();route=navs.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'ringkasan';render();}catch(error){$('#app').innerHTML=`<main class="boot"><div><h1>Data belum bisa dibuka</h1><p>${escape(error.message)}</p><button class="btn green" data-action="retry">Coba lagi</button></div></main>`;}}
boot();
